package stringalgo;
public class ZAlgorithm { public static boolean contains(String text,String pattern){String s=pattern+"$"+text;int[] z=new int[s.length()];for(int i=1,l=0,r=0;i<s.length();i++){if(i<=r)z[i]=Math.min(r-i+1,z[i-l]);while(i+z[i]<s.length()&&Character.toLowerCase(s.charAt(z[i]))==Character.toLowerCase(s.charAt(i+z[i])))z[i]++;if(i+z[i]-1>r){l=i;r=i+z[i]-1;}if(z[i]==pattern.length())return true;}return false;} }
